 static String diff(Object a,Object b,String path){if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;StringBuilder out=new StringBuilder();java.util.HashSet<String> keys=new java.util.HashSet<>();x.keys().forEachRemaining(keys::add);y.keys().forEachRemaining(keys::add);for(String key:keys){String d=diff(x.opt(key),y.opt(key),path+"/"+key);if(!d.isEmpty())out.append(d);if(out.length()>700)break;}return out.toString();}return java.util.Objects.equals(String.valueOf(a),String.valueOf(b))?"":path+" ["+String.valueOf(a).substring(0,Math.min(65,String.valueOf(a).length()))+" -> "+String.valueOf(b).substring(0,Math.min(65,String.valueOf(b).length()))+"]; ";}
