 check(!AppPreferences.getAutomaticRefresh(c),"Refresh setting retained");check(BetaGrowthStore.load(c,account)==null,"No opt in yet");BetaIdentity.save(c,"정식 검수 Alex");check(BetaIdentity.done(c),"Name setting completes optional identity setup");
 long now=System.currentTimeMillis();check(!BetaGrowthStore.start(c,account,now,true),"Production refuses synthetic mode");long first=LocalDate.now(BetaV4.ZONE).minusDays(29).atStartOfDay(BetaV4.ZONE).toInstant().toEpochMilli();check(BetaGrowthStore.start(c,account,first,false),"Explicit new-growth action creates separate profile");JSONObject archive=BetaGrowthStore.archive(c,account);check(archive.getJSONObject("rpg").getLong("xp")==46539&&archive.getJSONObject("rpg").getInt("level")==31,"Archive preserves legacy XP and level");check(archive.getJSONObject("rpg").optString("equipped_title").equals("qa_preserved_title"),"Legacy equipment retained in archive");check(raw(c,account).getJSONObject("future").getJSONObject("qa_preserved").getString("value").equals("must remain"),"Future legacy data retained");check(!BetaGrowthStore.start(c,account),"Repeat start never resets");
 for(int i=0;i<30;i++){long at=first+i*86400000L+3600000;BetaGrowthStore.confirm(c,account,at,at,false);}JSONObject state=BetaGrowthStore.load(c,account);check(state.getInt("level")>=30,"Thirty-day fixture reachesLv30");check(state.getJSONObject("honors").has("rpg4.days_14")&&state.getJSONObject("titles").has("rpg4.title_level_20"),"Expanded actual SQLite collectibles");long xp=state.getLong("total"),at=first+29*86400000L+3600000;ExecutorService pool=Executors.newFixedThreadPool(4);List<Future<Boolean>> futures=new ArrayList<>();for(int i=0;i<24;i++)futures.add(pool.submit(()->BetaGrowthStore.confirm(c,account,at,at,false)));for(Future<Boolean> future:futures)check(!future.get(20,TimeUnit.SECONDS),"Concurrent duplicate cannot pay");pool.shutdown();check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Concurrent/restart balance unchanged");
 check(BetaGrowthStore.equip(c,account,"rpg4.title_level_20"),"Added title equipment");check(!BetaGrowthStore.equip(c,account,"rpg4.title_level_100"),"Locked title refused");JSONObject backup=BetaGrowthStore.export(c,account);check(BetaGrowthStore.restore(c,account,backup),"Actual SQLite backup roundtrip");check(BetaGrowthStore.load(c,account).getLong("total")==xp,"No restore XP");check(BetaGrowthStore.archive(c,account).toString().equals(archive.toString()),"Immutable original archive");JSONObject bad=new JSONObject(backup.toString());bad.getJSONObject("state").put("total",xp+1);boolean rejected=false;try{BetaGrowthStore.restore(c,account,bad);}catch(Exception e){rejected=true;}check(rejected&&BetaGrowthStore.load(c,account).getLong("total")==xp,"Invalid backup atomic rejection");
 RpgProgressStore.reconcile(c,AppPreferences.loadSnapshot(c),new UsageLedgerDatabase.Data(),account);JSONObject oldAfter=RpgEngine.state(raw(c,account));for(String k:new String[]{"xp","level","awards","equipped_title"})check(oldAfter.get(k).toString().equals(archive.getJSONObject("rpg").get(k).toString()),"New active growth freezes original "+k);
 MainActivity home=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1600);waitForIdleSync();main(()->{View root=home.findViewById(android.R.id.content);check(root.findViewWithTag("beta996:tier-badge") instanceof TierCompanionView,"Actual stable home uses original tier badge");check(((TextView)root.findViewWithTag("beta996:name")).getText().toString().equals(BetaIdentity.name(c)),"Actual stable home name");check(root.findViewWithTag("beta996:level")!=null,"Actual stable home level");});main(home::finish);check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Home awards no XP");check(BetaCatalog.count(false)==37&&BetaCatalog.count(true)==24,"37 honors24 titles");result.putString("stream","Stable3.1.0 native: "+checks+" checks passed; signed upgrade/original fraction/archive/SQLite/24concurrent/backup/home; synthetic only.\n");finish(-1,result);
